import{_ as t,o as s,c as d,a2 as a}from"./chunks/framework.CNDaxUod.js";const u=JSON.parse('{"title":"v0.4 JSON Resume 结构迁移","description":"","frontmatter":{},"headers":[],"relativePath":"zh/migrations/v0.4-json-resume.md","filePath":"zh/migrations/v0.4-json-resume.md","lastUpdated":1788607300000}'),o={name:"zh/migrations/v0.4-json-resume.md"};function i(c,e,r,l,n,h){return s(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="v0-4-json-resume-结构迁移" tabindex="-1">v0.4 JSON Resume 结构迁移 <a class="header-anchor" href="#v0-4-json-resume-结构迁移" aria-label="Permalink to &quot;v0.4 JSON Resume 结构迁移&quot;">​</a></h1><p>Web Resume v0.4 开始让新建及转换后的文档尽可能采用 JSON Resume 字段结构。旧版 YAML 在 v0.4 期间仍可直接读取，不会在加载时自动改写。</p><h2 id="是否需要迁移" tabindex="-1">是否需要迁移 <a class="header-anchor" href="#是否需要迁移" aria-label="Permalink to &quot;是否需要迁移&quot;">​</a></h2><p>如果文件使用 <code>contact</code>、<code>project.sets</code>、<code>skill.sets</code>、<code>education.histories</code> 等结构，它属于旧版格式。你可以继续使用，也可以转换后逐步接入 JSON Resume 生态。</p><p>标准格式通常使用 <code>basics.email</code>、<code>projects[]</code>、<code>skills[]</code>、<code>education[]</code> 等字段。YAML 或 JSON 只是文件语法，不影响采用 JSON Resume 数据结构。</p><h2 id="在编辑器中转换" tabindex="-1">在编辑器中转换 <a class="header-anchor" href="#在编辑器中转换" aria-label="Permalink to &quot;在编辑器中转换&quot;">​</a></h2><ol><li>在编辑器中加载旧版简历。</li><li>选择页面提示中的 <strong>检查并转换</strong>。</li><li>阅读需要人工处理的字段提示。</li><li>选择 <strong>转换并写回编辑器</strong>。</li><li>检查预览和 YAML；如需恢复，立即使用编辑器撤销。</li></ol><p>只有确认后，编辑器文本才会改变。原始 URL 或磁盘文件不会被浏览器直接覆盖。</p><p>转换器不会擅自判断以下内容：</p><ul><li><code>project</code> 中的条目究竟是工作还是项目；</li><li><code>certificate</code> 中的条目究竟是奖项、证书还是出版物；</li><li>自由文本地址应如何拆分成城市、地区和国家；</li><li>非标准日期应如何转换成 <code>YYYY</code>、<code>YYYY-MM</code> 或 <code>YYYY-MM-DD</code>。</li></ul><p>无法安全转换的数据会尽量保存在 <code>x-web-resume</code> 中并显示提示。转换序列化暂时无法保留 YAML 注释，因此有注释时也会提示。</p><p>转换器不认识的字段会保存在 <code>x-web-resume.legacyFields</code> 中。键名采用字段原始位置的 <a href="https://www.rfc-editor.org/rfc/rfc6901" target="_blank" rel="noreferrer">JSON Pointer</a> 路径，既能恢复自定义数据，也不需要复制整份旧版文档。</p><h2 id="使用命令行转换" tabindex="-1">使用命令行转换 <a class="header-anchor" href="#使用命令行转换" aria-label="Permalink to &quot;使用命令行转换&quot;">​</a></h2><p>只检查，不写文件：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate:resume</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./resume.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span></code></pre></div><p>旧格式需要迁移或校验失败时，检查命令以状态码 <code>1</code> 退出。</p><p>生成一份转换后的副本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate:resume</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./resume.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./resume.v0.4.yml</span></span></code></pre></div><p>命令不会隐式覆盖输入文件。建议先查看转换提示并比较差异，再决定是否替换原文件。</p><h2 id="主要字段变化" tabindex="-1">主要字段变化 <a class="header-anchor" href="#主要字段变化" aria-label="Permalink to &quot;主要字段变化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>旧版字段</th><th>v0.4 字段</th></tr></thead><tbody><tr><td><code>basics.avatar</code></td><td><code>basics.image</code></td></tr><tr><td><code>basics.bio</code></td><td><code>basics.summary</code></td></tr><tr><td><code>contact.email</code></td><td><code>basics.email</code></td></tr><tr><td><code>contact.phone</code></td><td><code>basics.phone</code></td></tr><tr><td><code>contact.blog</code></td><td><code>basics.url</code></td></tr><tr><td>其他 <code>contact.*</code></td><td><code>basics.profiles[]</code></td></tr><tr><td><code>education.histories[]</code></td><td><code>education[]</code></td></tr><tr><td><code>work.sets[]</code></td><td><code>work[]</code></td></tr><tr><td><code>project.sets[]</code></td><td><code>projects[]</code></td></tr><tr><td><code>skill.sets[]</code></td><td><code>skills[]</code></td></tr><tr><td><code>certificate.histories[]</code></td><td><code>awards[]</code>，转换后需人工复核</td></tr><tr><td><code>start</code> / <code>end</code></td><td><code>startDate</code> / <code>endDate</code></td></tr></tbody></table><p>板块标题、图标、条目 Logo、展开状态、徽章、自定义资料、<code>other</code> 内容和展示顺序统一放在 <code>x-web-resume</code> 扩展中。</p><h2 id="兼容与回退" tabindex="-1">兼容与回退 <a class="header-anchor" href="#兼容与回退" aria-label="Permalink to &quot;兼容与回退&quot;">​</a></h2><ul><li>v0.4 保留旧版格式的加载和渲染能力。</li><li>标准无法表达的展示信息只使用根级 <code>x-web-resume</code> 扩展。</li><li>浏览器转换是一次可撤销操作；命令行转换默认写入新文件。</li><li><code>volunteer</code>、<code>publications</code>、<code>languages</code>、<code>interests</code> 和 <code>references</code> 等标准板块均可渲染。</li><li>未来如果移除旧格式读取，必须随稳定版数据契约提供迁移说明和经过测试的转换路径。</li></ul><p>更完整的字段取舍与设计依据见 <a href="./../reference/json-resume-compatibility">JSON Resume 兼容性评估</a>，英文版见 <a href="./../../migrations/v0.4-json-resume">v0.4 migration guide</a>。</p>',25)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
